    .hero-title {
      animation: fadeInDown 1s ease-out;
    }

    @keyframes fadeInDown {
      from {
        opacity: 0;
        transform: translateY(-30px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    .card {
      animation: fadeInUp 0.6s ease-out forwards;
      opacity: 0;
    }

    .card:nth-child(1) {
      animation-delay: 0.2s;
    }

    .card:nth-child(2) {
      animation-delay: 0.4s;
    }

    .card:nth-child(3) {
      animation-delay: 0.6s;
    }

    @keyframes fadeInUp {
      from {
        opacity: 0;
        transform: translateY(30px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    .counter {
      animation: fadeInUp 0.8s ease-out forwards;
      opacity: 0;
      animation-delay: 1s;
    }

    .btn-start {
      transition: all 0.3s ease;
    }

    .btn-start:hover {
      transform: scale(1.05);
    }

    @media (prefers-reduced-motion: reduce) {
      .btn-start:hover {
        transform: none;
      }
    }
  }

  column {
    column class="gradient-bg" gap=0 pad=0 align=center justify=center style="min-height: 100vh; position: relative; overflow: hidden;" {
      column gap=4 align=center justify=center style="z-index: 1;" {
        title "Nimbus" class="hero-title" style="font-size: 4rem; margin: 0; background: linear-gradient(135deg, #fff 0%, #f0f0f0 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;"
        text "La plataforma moderna para tu negocio" large style="color: rgba(255,255,255,0.9); max-width: 600px; text-align: center;"
        button "Empezar" primary class="btn-start" style="margin-top: 2rem; padding: 12px 32px; font-size: 1rem;"
