      title "¿Por qué Nimbus?" muted style="text-align: center; margin-bottom: 2rem;"

      grid cols=3 gap=4 style="max-width: 1200px; margin: 0 auto;" {
        card class="card" pad=4 gap=2 align=center {
          icon "Zap" size=32 primary
          title "Rápido" small
          text "Velocidad ultrarrápida en cada operación" muted small
        }

        card class="card" pad=4 gap=2 align=center {
          icon "Smile" size=32 primary
          title "Simple" small
          text "Interfaz intuitiva y fácil de usar" muted small
        }

        card class="card" pad=4 gap=2 align=center {
          icon "Lock" size=32 primary
          title "Abierto" small
          text "Totalmente flexible y personalizable" muted small
        }
      }
    }

    column gap=4 align=center justify=center style="min-height: 60vh; background: #fff; border-top: 1px solid #e0e0e0;" pad=6 {
      Counter target=12000 label="Usuarios en todo el mundo" class="counter"
