component MeshBackground {
  ref canvas
  state animationId = null

  mount {
    const c = canvas
    const ctx = c.getContext("2d")
    let time = 0

    const resize = () => {
      c.width = c.offsetWidth * devicePixelRatio
      c.height = c.offsetHeight * devicePixelRatio
      ctx.scale(devicePixelRatio, devicePixelRatio)
    }
    resize()

    const animate = () => {
      time += 0.0003
      ctx.fillStyle = "url(#gradient)"
      const gradient = ctx.createLinearGradient(0, 0, c.offsetWidth, c.offsetHeight)
      gradient.addColorStop(0, `hsl(${200 + Math.sin(time) * 20}, 70%, 60%)`)
      gradient.addColorStop(0.5, `hsl(${240 + Math.cos(time * 0.7) * 20}, 80%, 50%)`)
      gradient.addColorStop(1, `hsl(${280 + Math.sin(time * 0.5) * 20}, 75%, 55%)`)
      ctx.fillStyle = gradient
      ctx.fillRect(0, 0, c.offsetWidth, c.offsetHeight)
      animationId = requestAnimationFrame(animate)
    }
    animate()

    window.addEventListener("resize", resize)
    cleanup {
      window.removeEventListener("resize", resize)
      cancelAnimationFrame(animationId)
    }
  }

  canvas width=800 height=600 style="width: 100%; height: 100%; display: block;"
}

component Counter(target = 12000) {
  state current = 0
  ref container

  effect {
    const prefersReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    if prefersReduced {
      current = target
      return
    }

    let animationFrameId = null
    const startTime = Date.now()
    const duration = 2000

    const animate = () => {
      const elapsed = Date.now() - startTime
      const progress = Math.min(elapsed / duration, 1)
      current = Math.floor(progress * target)

      if progress < 1 {
        animationFrameId = requestAnimationFrame(animate)
      }
    }

    animationFrameId = requestAnimationFrame(animate)

    return () => {
      if animationFrameId {
        cancelAnimationFrame(animationFrameId)
      }
    }
  }

  text `${current.toLocaleString()}+` ref=container style="font-size: 4rem; font-weight: bold; color: var(--a-primary);"
}

page Home "/" {
  style {
    .hero-section {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
      background: #0a0e27;
    }
    .mesh-bg {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      z-index: 1;
      opacity: 0.8;
    }
    .hero-content {
      position: relative;
      z-index: 2;
      text-align: center;
      color: white;
    }
    .hero-title {
      font-size: clamp(3rem, 10vw, 6rem);
      font-weight: 800;
      margin: 0;
      letter-spacing: -2px;
      background: linear-gradient(135deg, #60a5fa, #a78bfa);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .hero-subtitle {
      font-size: clamp(1rem, 3vw, 1.5rem);
      color: #cbd5e1;
      margin-top: 1rem;
      margin-bottom: 3rem;
    }
    .cta-button {
      padding: 1rem 2.5rem;
      font-size: 1.1rem;
      font-weight: 600;
      background: linear-gradient(135deg, #60a5fa, #a78bfa);
      color: white;
      border: none;
      border-radius: 50px;
      cursor: pointer;
      transition: transform 0.3s ease, box-shadow 0.3s ease;
      box-shadow: 0 10px 30px rgba(96, 165, 250, 0.3);
    }
    .cta-button:hover {
      transform: scale(1.08);
      box-shadow: 0 15px 40px rgba(96, 165, 250, 0.5);
    }
    .cta-button:active {
      transform: scale(0.98);
    }
    @media (prefers-reduced-motion: reduce) {
      .cta-button {
        transition: none;
      }
      .cta-button:hover {
        transform: none;
      }
    }
    .cards-section {
      padding: 6rem 2rem;
      max-width: 1200px;
      margin: 0 auto;
      background: #0f172a;
    }
    .cards-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 2rem;
      margin-top: 3rem;
    }
    .feature-card {
      background: linear-gradient(135deg, rgba(96, 165, 250, 0.1), rgba(167, 139, 250, 0.1));
      border: 1px solid rgba(96, 165, 250, 0.2);
      border-radius: 12px;
      padding: 2rem;
      text-align: center;
      color: white;
      transition: transform 0.3s ease, border-color 0.3s ease;
    }
    .feature-card:hover {
      transform: translateY(-5px);
      border-color: rgba(96, 165, 250, 0.5);
    }
    .feature-card h3 {
      font-size: 1.5rem;
      margin: 0 0 1rem 0;
      color: #60a5fa;
    }
    .feature-card p {
      margin: 0;
      color: #cbd5e1;
      line-height: 1.6;
    }
    @media (prefers-reduced-motion: reduce) {
      .feature-card {
        transition: none;
      }
      .feature-card:hover {
        transform: none;
      }
    }
    .users-section {
      padding: 4rem 2rem;
      text-align: center;
      background: linear-gradient(135deg, #0f172a, #1a1f3a);
      color: white;
    }
    .users-label {
      font-size: 1.2rem;
      color: #cbd5e1;
      margin-bottom: 1rem;
    }
  }

  column gap=0 {
    row class="hero-section" {
      column class="mesh-bg" {
        MeshBackground
      }
      column class="hero-content" gap=4 {
        title "Nimbus" class="hero-title"
        text "La plataforma que transforma tu productividad" class="hero-subtitle"
        button "Empezar" class="cta-button"
      }
    }

    column class="cards-section" gap=4 {
      title "¿Por qué elegir Nimbus?" tag=h2 style="text-align: center; color: white; font-size: 2.5rem; margin: 0;"
      column class="cards-grid" {
        column class="feature-card" animate=fade delay=0 {
          title "Rápido" class="feature-card h3"
          text "Velocidad ultrarrápida en cada operación, optimizado para máximo rendimiento"
        }
        column class="feature-card" animate=fade delay=200 {
          title "Simple" class="feature-card h3"
          text "Interfaz intuitiva que cualquiera puede dominar en minutos, sin curva de aprendizaje"
        }
        column class="feature-card" animate=fade delay=400 {
          title "Abierto" class="feature-card h3"
          text "API completamente abierta para integrar con tus herramientas favoritas"
        }
      }
    }

    column class="users-section" align=center {
      text "Confían en nosotros" class="users-label"
      reveal {
        Counter target=12000
      }
    }
  }
}

