import FeatureCard from './FeatureCard';

interface Feature {
  id: number;
  title: string;
  description: string;
}

export default function Features() {
  const features: Feature[] = [
    {
      id: 1,
      title: 'Rápido',
      description: 'Velocidad de carga ultrarrápida con optimizaciones avanzadas',
    },
    {
      id: 2,
