      id: 3,
      title: 'Abierto',
      description: 'API abierta y extensible para integración sin límites',
    },
  ];

  const [visibleCards, setVisibleCards] = createSignal<number[]>([]);

  createEffect(() => {
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    features.forEach((feature, index) => {
      const delay = prefersReduced ? 0 : index * 300;
