import { createSignal, createEffect, onMount } from 'solid-js';

export default function UserCount() {
  const [count, setCount] = createSignal(0);
  const [hasStarted, setHasStarted] = createSignal(false);
  const TARGET = 12000;
  const DURATION = 2000; // 2 seconds

  let sectionRef: HTMLDivElement | undefined;

  onMount(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !hasStarted()) {
          setHasStarted(true);
          const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

          if (prefersReduced) {
            setCount(TARGET);
          } else {
            const startTime = Date.now();
            const interval = setInterval(() => {
              const elapsed = Date.now() - startTime;
              const progress = Math.min(elapsed / DURATION, 1);
              setCount(Math.floor(progress * TARGET));

              if (progress === 1) {
                clearInterval(interval);
              }
            }, 16);
          }
        }
      },
      { threshold: 0.5 }
    );

    if (sectionRef) {
      observer.observe(sectionRef);
    }

    return () => {
      if (sectionRef) {
        observer.unobserve(sectionRef);
      }
    };
  });

  const formattedCount = () => {
    return count().toLocaleString('es-ES');
  };

  return (
    <section
      ref={sectionRef}
      class="py-20 px-4 bg-gradient-to-r from-purple-600 to-pink-600"
    >
      <div class="max-w-6xl mx-auto text-center">
        <div class="text-6xl md:text-8xl font-bold text-white mb-4">
          {formattedCount()}+
        </div>
        <p class="text-xl md:text-2xl text-purple-100">
          Usuarios confían en Nimbus
        </p>
      </div>
    </section>
  );
}

