import { createSignal, onMount, createEffect } from 'solid-js';
import './Stats.css';

export default function Stats() {
  const [count, setCount] = createSignal(0);
  const [isVisible, setIsVisible] = createSignal(false);
  const TARGET = 12000;
  const DURATION = 2000; // 2 seconds

  onMount(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !isVisible()) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.5 }
    );

    const element = document.getElementById('stats-counter');
    if (element) {
      observer.observe(element);
    }
  });

  createEffect(() => {
    if (isVisible()) {
      const prefersReducedMotion = window.matchMedia(
        '(prefers-reduced-motion: reduce)'
      ).matches;

      if (prefersReducedMotion) {
        setCount(TARGET);
      } else {
        const startTime = performance.now();

        const animate = (currentTime: number) => {
          const elapsed = currentTime - startTime;
          const progress = Math.min(elapsed / DURATION, 1);
          const currentCount = Math.floor(progress * TARGET);
          setCount(currentCount);

          if (progress < 1) {
            requestAnimationFrame(animate);
          }
        };

        requestAnimationFrame(animate);
      }
    }
  });

  return (
    <section class="py-20 px-4 bg-black border-t border-gray-900">
      <div class="max-w-6xl mx-auto text-center">
        <div id="stats-counter" class="stats-container">
          <div class="text-6xl md:text-8xl font-bold mb-4">
            <span class="counter-number">{count().toLocaleString()}</span>
            <span class="text-blue-500">+</span>
          </div>
          <p class="text-xl text-gray-400">Usuarios confían en Nimbus</p>
        </div>
      </div>
    </section>
  );
}

